"""Full-text appraisal, batch 2 (2026-11-17): four Included tier-A cases with open-access full text.

sosa-gomez-2026, haque-2025, smith-2025, downar-2012.

Tier changes under the section 6 rule:
  sosa-gomez-2026 A -> C   (no measure before, five-day observation: flag no-followup; regression and setting change)
  haque-2025 A -> B        (no standardised measure, no reversal)
  smith-2025 A -> C        (first assessed 7 years later; antipsychotic history after the injury not reported)
downar-2012: outcome.reversal recoded to On-off rechallenge (relapse two months after the course, second course worked at once).
"""
import sys
sys.path.insert(0, "scripts")
from lib_code import Batch, ev, track, T, A, J, N, H  # noqa: E402

b = Batch("2026-11-17", source="PMC open-access full text, via Europe PMC")

# ------------------------------------------------------------------ sosa-gomez-2026
b.code("sosa-gomez-2026",
       tracks=[track("23-year-old woman, 32 weeks pregnant", 23, "F", [
           ev("onset", -8, "years", "Depression from adolescence, after childhood abuse (her account)", "approx"),
           ev("assessment", -7, "years", "Serious suicide attempts in 2017 and 2019; repeated admissions; seizure disorder for years", "approx", to=-5),
           ev("assessment", -2, "days", "Admitted to a state psychiatric centre: self-injury (choking herself, punching her abdomen), depression, voices; prescribed fluoxetine 40 mg, olanzapine 15 mg, levetiracetam, adherence poor in custody and in hospital", "approx"),
           ev("exposure_start", 0, "days", "Generalised tonic-clonic seizure; transferred; IV levetiracetam; brief intensive care for low blood pressure"),
           ev("cointervention", 0, "days", "Moved from the state centre to a medical ward; no antidepressant or antipsychotic given; levetiracetam 1,500 mg IV twice daily"),
           ev("best_response", 1, "days", "Psychiatric review: euthymic, organised, no psychosis or suicidal thoughts; no memory of the behaviours that led to admission", "approx", state="Remitted",
              scores=[{"scale": "PHQ-9", "value": 0}, {"scale": "BPRS", "value": 18}]),
           ev("follow_up", 5, "days", "Symptom-free for the five-day stay, off psychotropics; back to the state hospital", state="Remitted"),
       ])],
       unexpectedness=T(era=("borderline", "ECT makes an antidepressant effect of a generalised seizure predictable in principle."),
                        secondary=("borderline", "Self-injury in custody and a state hospital, poor adherence and a trauma history: the crisis may have been situational or dissociative, eased by the move to a medical ward."),
                        base_rate=("borderline", "No measure before the seizure, and she had had many seizures over the years.")),
       attribution=A(1, 0, 1, 0, 0, "Only post-seizure scores; setting change, levetiracetam and stopping psychotropics named by the authors, not separated."),
       jbi=J("YUYYYYYY"),
       note="Five days of observation is effectively no follow-up (flag no-followup).",
       fix={"tier": "C", "flags": ["no-followup"],
            "summary": "A pregnant 23-year-old admitted for self-injury with depression and voices was calm, euthymic and free of psychosis on review a day after a generalised seizure, and stayed so for a five-day stay off psychotropics.",
            "caveat": "She was reviewed after moving from custody and a state hospital to a medical ward, with no score from before the seizure, so a settling crisis explains it as well."})
b.reading("sosa-gomez-2026",
          nulls=N(natural_history=("Possible", "Episodic depression and self-injury with long quiet stretches would look like this."),
                  regression=("Likely", "Admitted at a crisis peak in a highly stressful setting; calm days later on a medical ward is what regression looks like."),
                  misdiagnosis=("Possible", "Functional seizures (the authors considered them), dissociation (no memory of the behaviours) or trauma-related symptoms."),
                  cointervention=("Possible", "A change of setting, intravenous levetiracetam and intensive care."),
                  nonspecific=("Possible", "Postictal state and levetiracetam can flatten behaviour, though she was alert and engaged."),
                  expectancy=("Unlikely", "Nothing to expect from."),
                  reporting=("Likely", "No score before the seizure, five days of observation, and no history from her about past episodes.")),
          verdict="Doesn't beat the null",
          note="Remission was judged a day after a seizure and a move out of custody, with nothing measured before and nothing after five days. She has had seizures for years, so if seizures lifted her mood it should have shown before.",
          hyps=[H("The crisis settled with the move from custody and a state hospital to a medical ward.",
                  "Acute stress and confinement → self-injury and voices → transfer to a medical ward, intensive care, attention → crisis eases within days",
                  ["Social and environmental change"], "Fits",
                  "Self-injury happened in custody and on admission; calm within days of a medical admission.",
                  "Voices and depression had reportedly persisted across settings for years.",
                  "Moderate", "No measure before the seizure, so we don't know how ill she was in the days before it.",
                  "Her symptoms on return to the state hospital, still off psychotropics."),
                H("The generalised seizure acted like a single ECT treatment.",
                  "Generalised tonic-clonic seizure → widespread network and neurotrophic changes, as in ECT → mood and psychosis lift",
                  ["Network reset (seizure, coma, anaesthesia)", "Neuroplasticity"], "Fits",
                  "A generalised seizure came just before the remission.",
                  "One ECT treatment rarely produces remission, and she has had many seizures without one.",
                  "Low", "Her seizure history: if earlier seizures never helped her mood, a seizure effect is unlikely.",
                  "Mood records around her previous seizures.")],
          related=[("kim-2016", "Treatment-resistant depression remitting after an accidental seizure during rTMS"),
                   ("silverstone-1991", "Depression improving after spontaneous seizures following failed ECT")])

# ------------------------------------------------------------------ haque-2025
b.code("haque-2025",
       tracks=[track("Ms B.", 42, "F", [
           ev("onset", -20, "years", "Problem drinking from her early 20s after a depressive episode; worse in her 30s during an abusive relationship", "approx"),
           ev("treatment_failed", -2, "weeks", "Group support, counselling, gabapentin and naltrexone had failed; naltrexone stopped two weeks before, gabapentin continued at a stable dose"),
           ev("assessment", -1, "weeks", "Drinking two bottles of wine a day", "approx"),
           ev("exposure_start", 0, "days", "Fell downstairs drunk: head injury, loss of consciousness, GCS 14"),
           ev("cointervention", 0, "days", "Intensive care for neuromonitoring and an alcohol-withdrawal protocol"),
           ev("assessment", 1, "days", "CT: new 1 cm haemorrhagic contusion in the left orbitofrontal cortex"),
           ev("first_change", 3, "weeks", "TBI clinic: cravings and interest in alcohol gone; abstinent for the first time in years; anosmia and loss of taste, insomnia, mild memory problems", "at most", state="Remitted"),
           ev("assessment", 1, "months", "CT: contusion resolved; mild cerebellar atrophy", "approx"),
           ev("relapse", 4, "months", "One relapse with work stress (pandemic)", "approx"),
           ev("best_response", 8, "months", "Abstinent again", "approx", state="Remitted"),
           ev("follow_up", 12, "months", "Abstinent for the four months before review (early remission); discharged", state="Remitted"),
       ])],
       lesion={"kind": "Injury", "side": "Left", "regions": ["Orbitofrontal"],
               "specific": "1 cm haemorrhagic contusion in the left orbitofrontal cortex (day-2 CT), with trace subarachnoid blood over the left anterior temporal lobe; traced in MNI space and network-mapped",
               "aetiology": "Trauma", "imaging": "CT", "mappable": "Coordinates"},
       unexpectedness=T(base_rate=("borderline", "A near-fatal drunken fall and an intensive care stay is a classic turning point for drinkers.")),
       attribution=A(1, 0, 1, 0, 1, "No new medicines; gabapentin stable, naltrexone stopped before; abstinence self-reported, no biomarkers."),
       jbi=J("YYYYYYYY"),
       fix={"tier": "B",
            "caveat": "Post-traumatic loss of smell and taste took away the sensory pull of wine, a duller route to the same result."})
b.reading("haque-2025",
          nulls=N(natural_history=("Possible", "Alcohol use disorder does remit without treatment, often after a crisis."),
                  regression=("Unlikely", "Not presenting at a drinking peak; seen for the head injury."),
                  misdiagnosis=("Unlikely", "Clear chronic alcohol use disorder."),
                  cointervention=("Possible", "Supervised withdrawal in intensive care; a frightening injury; gabapentin continued."),
                  nonspecific=("Possible", "Anosmia and loss of taste removed wine's taste and smell; mild memory problems."),
                  expectancy=("Unlikely", "Nothing was offered for drinking."),
                  reporting=("Possible", "Self-reported abstinence, no biomarkers.")),
          verdict="Beats the null",
          note="Craving itself vanished, not just drinking, after a small lesion in a known addiction node, and it held through a year with one stress-linked lapse. The anosmia is the dull rival the authors didn't discuss.",
          hyps=[H("Disrupting the orbitofrontal node of the addiction network abolished craving (the authors' lesion-network reading).",
                  "1 cm left orbitofrontal contusion → disconnection of a hub that potentiates urges via projections to the dorsal striatum → craving and compulsive drinking stop",
                  ["Lesion disconnection"], "Fits",
                  "The lesion's connectivity converges on the published smoking-remission network (inverse, r = −0.59, permutation p = 0.04).",
                  "The contusion had resolved on CT by a month while abstinence continued; matching with the opposite sign needs the claim that any disruption works; one relapse.",
                  "Moderate", "The connectivity match is opposite in sign to the reference map, so the result depends on accepting that disruption in either direction works.",
                  "Other orbitofrontal lesions in the literature: do they end addictions, and with which connectivity sign?"),
                H("Post-traumatic anosmia and loss of taste removed the sensory reward of wine.",
                  "Frontal head injury → olfactory damage → wine no longer smells or tastes of anything → cue-driven craving falls",
                  ["Sensory input change"], "Fits",
                  "Persistent anosmia and ageusia at the clinic visit; much of wine's pull is smell and taste.",
                  "Craving isn't only sensory, and she relapsed under stress (smell then unknown).",
                  "Low", "Whether smell and taste had recovered by the time of the relapse isn't reported.",
                  "Serial smell testing against craving: craving returning as smell returns would favour this."),
                H("A near-fatal drunken fall and intensive care stay reorganised her motivation to drink.",
                  "Frightening alcohol-related injury → a turning point → stops drinking",
                  ["Meaning and life reorganisation", "Threat and arousal"], "Fits",
                  "Drinkers often stop after a frightening alcohol-related injury.",
                  "She described losing the urge, not resisting it; earlier crises hadn't stopped her.",
                  "Low", "No account of how she understood the injury.",
                  "Craving measures that separate losing the urge from resisting it.")],
          related=[("naqvi-2007", "Insula lesions ending smoking, the founding lesion-addiction series"),
                   ("joutsa-2022", "Lesion network for addiction remission (context)"),
                   ("yousefzadeh-fard-2013", "Insula strokes ending opium addiction")])

# ------------------------------------------------------------------ smith-2025
b.code("smith-2025",
       tracks=[track("32-year-old man", 32, "M", [
           ev("onset", -2, "years", "Paranoid delusions (tracking chip in his ear) and five punishing command voices; two admissions", "at least"),
           ev("assessment", -1, "days", "Earlier treatment abandoned because of sedation; olanzapine prescribed but not yet started (awaiting mail-order)", "approx"),
           ev("exposure_start", 0, "days", "Self-inflicted submental gunshot wound: large left frontal haemorrhage, fragments in the frontal lobe; GCS 3"),
           ev("cointervention", 0, "days", "Emergency craniotomy: debridement, haematoma evacuation, reconstruction"),
           ev("assessment", 1, "months", "Following commands; to inpatient rehabilitation: poor insight, impulsive, needed 24-hour supervision", "approx"),
           ev("assessment", 7, "years", "Admitted for breakthrough complex partial seizures: FAB 4/18, transcortical motor aphasia, distractibility, compulsive spending, memory loss; needs a full-time carer",
              scores=[{"scale": "FAB", "value": 4, "higher_is_better": True}]),
           ev("best_response", 7, "years", "Patient and mother: no voices, paranoia, depression or suicidal thoughts since recovering from the injury", "at most", state="Remitted"),
           ev("follow_up", 7, "years", "Good-natured, no psychotic features on interview and later phone interviews", state="Remitted"),
       ])],
       lesion={"kind": "Injury", "side": "Bilateral", "regions": ["Frontal, other", "Temporal, lateral"],
               "specific": "Acute large left frontal haemorrhage; at 7 years, extensive bifrontal and moderate left temporal encephalomalacia on CT",
               "aetiology": "Trauma", "imaging": "CT", "mappable": "Figure"},
       unexpectedness=T(era=("borderline", "Frontal leucotomy's effect on psychosis is well known, so the direction was predictable once the frontal damage was seen.")),
       attribution=A(1, 0, 0, 0, 0, "First assessed 7 years after the injury, so the timing of the change is unknown; antipsychotic treatment after the injury isn't reported."),
       jbi=J("YYYYYYYY"),
       note="Whether he took antipsychotics in the 7 years after the injury isn't reported.",
       fix={"tier": "C",
            "caveat": "He was first assessed 7 years later, with severe frontal damage and aphasia, so lost drive and speech could hide psychosis as much as end it."})
b.reading("smith-2025",
          nulls=N(natural_history=("Possible", "Some schizophrenia settles over seven years, though rarely so completely."),
                  regression=("Unlikely", "Not judged against a peak."),
                  misdiagnosis=("Unlikely", "A well-described paranoid psychosis with command hallucinations."),
                  cointervention=("Possible", "Seven years under his mother's care with unknown medication; levetiracetam for seizures."),
                  nonspecific=("Likely", "Severe frontal damage: apathy, aphasia with short answers, stimulus-boundedness. Less drive and less speech can mean less voiced psychosis."),
                  expectancy=("Unlikely", "Not relevant."),
                  reporting=("Possible", "Mother's report and interviews at 7 years; no psychosis scale.")),
          verdict="Doesn't beat the null",
          note="A modern leucotomy by gunshot: psychosis gone, but so is much of frontal function. With transcortical motor aphasia and apathy, whether the voices stopped or he stopped acting on and talking about them can't be told apart.",
          hyps=[H("Widespread frontal damage removed the drive and elaboration that kept the psychosis active, as leucotomy did.",
                  "Bifrontal destruction → apathy, reduced initiative and emotional tone → delusions and voices no longer elaborated or acted on",
                  ["Lesion disconnection", "Global suppression (sedation, apathy, cognitive loss)"], "Can't judge",
                  "FAB 4/18, apathy and stimulus-boundedness; the classic leucotomy picture.",
                  "He denies voices outright and is described as good-natured and sociable with people he knows.",
                  "Moderate", "Aphasia limits how much inner experience he can report, so absent voices can't be confirmed.",
                  "A structured psychosis interview adapted for aphasia, or observation for responding to voices."),
                H("Specific disconnection of frontal-temporal circuits generating the hallucinations (left temporal damage too).",
                  "Left frontal and temporal destruction → loss of the speech-production and auditory-cortex coupling thought to generate voices → voices stop",
                  ["Lesion disconnection"], "Can't judge",
                  "Voices were the core symptom; the left temporal lobe was damaged too.",
                  "The damage is so extensive that any specific claim is untestable in this case.",
                  "Low", "No timing: we don't know if the voices stopped at once or over years.",
                  "Lesion network mapping of the 7-year CT against the hallucination lesion network.")],
          related=[])

# ------------------------------------------------------------------ downar-2012
b.code("downar-2012",
       tracks=[track("43-year-old woman", 43, "F", [
           ev("onset", -28, "years", "Anorexia nervosa at 15 (BMI 12.9); binge-eating soon after", "approx"),
           ev("assessment", -23, "years", "Self-induced vomiting from 20; first depression", "approx"),
           ev("treatment_failed", -13, "years", "Several SSRIs, trazodone, desipramine, risperidone, quetiapine, methylphenidate, modafinil; four inpatient and six day-hospital programmes; CBT, mindfulness, trauma therapy", "approx", to=-0.5),
           ev("assessment", -4, "years", "After her marriage ended: one or two binge–purge episodes a day, each at least 5 hours", "approx"),
           ev("treatment_failed", -6, "months", "Six-week inpatient programme normalised eating; complete relapse 4 days after discharge", "approx"),
           ev("exposure_start", 0, "days", "Neuronavigated 10 Hz rTMS to dorsomedial prefrontal cortex, both sides, 20 weekday sessions, for depression; venlafaxine and desvenlafaxine stable for 3 months. Two 5-hour binge–purge episodes daily for 5 months",
              scores=[{"scale": "HAM-D17", "value": 26}, {"scale": "BDI-II", "value": 28}]),
           ev("first_change", 1, "days", "Binge-eating and purging stopped abruptly after the second session", state="Remitted"),
           ev("relapse", 7, "days", "One binge–purge episode a day during sessions 6–10"),
           ev("best_response", 14, "days", "Binges gone again from session 11; depression remitting", scores=[{"scale": "BDI-II", "value": 7}], state="Remitted"),
           ev("exposure_stop", 25, "days", "Course ends after 20 sessions", scores=[{"scale": "HAM-D17", "value": 0}]),
           ev("cointervention", 89, "days", "Contact with her former husband, a major stressor", "approx"),
           ev("relapse", 90, "days", "Single binge–purge episodes on days 65, 70 and 71 after the course"),
           ev("assessment", 107, "days", "Before the second course", scores=[{"scale": "BDI-II", "value": 20}, {"scale": "HAM-D17", "value": 11}]),
           ev("exposure_restart", 107, "days", "Second 20-session course"),
           ev("best_response", 108, "days", "Binge-eating and purging stopped after the first session", state="Remitted"),
           ev("follow_up", 132, "days", "In remission from both through the rest of the second course", "approx", state="Remitted",
              scores=[{"scale": "BDI-II", "value": 7}, {"scale": "HAM-D17", "value": 7}]),
       ])],
       unexpectedness=T(),
       attribution=A(1, 0, 1, 2, 1, "Daily binge log, not a standardised eating-disorder scale (measure 0); antidepressants stable; expectancy and contact discussed."),
       jbi=J("YYYYYYYY"),
       fix={"outcome.reversal": "On-off rechallenge",
            "summary": "A 43-year-old's twice-daily five-hour binge–purge episodes, refractory for two decades, stopped after the second session of rTMS given for depression; they returned two months after the course and stopped again after the first session of a second course."})
b.reading("downar-2012",
          nulls=N(natural_history=("Unlikely", "Twenty years of refractory illness and five months of twice-daily episodes, stopping after session 2."),
                  regression=("Unlikely", "Steady at the same severity for five months."),
                  misdiagnosis=("Unlikely", "Long, well-documented eating disorder."),
                  cointervention=("Possible", "Daily clinic contact for four weeks; antidepressants unchanged for three months."),
                  nonspecific=("Unlikely", "She became more active and functional."),
                  expectancy=("Possible", "Open-label daily treatment; nobody expected an eating effect, but the second course was explicitly to prevent relapse."),
                  reporting=("Possible", "A self-kept daily log; no eating-disorder scale.")),
          verdict="Beats the null",
          note="An abrupt stop after two sessions, a return two months after the course ended, and a second stop after one session of a second course. In both courses the bingeing improved before the mood did, which argues against eating simply following mood.",
          hyps=[H("High-frequency dorsomedial prefrontal stimulation strengthened top-down control over the binge urge.",
                  "10 Hz rTMS at dorsomedial prefrontal cortex → more activity in a control node underactive in bulimia → urge-to-act coupling weakened → binges and purges stop; mood follows",
                  ["Stimulation of a circuit"], "Fits",
                  "Change after session 2 and after session 1 of the second course; she described less urgency and more choice; eating changed before mood.",
                  "No impulsivity measure; one patient; open label.",
                  "Moderate", "No standardised eating-disorder or impulsivity measure, so the mechanism rests on her description.",
                  "A sham-controlled course with stop-signal or delay-discounting tasks before and after."),
                H("The antidepressant effect of rTMS lifted the mood that drove the bingeing.",
                  "rTMS → antidepressant effect → less dysphoria → less bingeing",
                  ["Stimulation of a circuit", "Neuroplasticity"], "Doesn't fit",
                  "Depression and bingeing remitted in the same course and returned together.",
                  "Bingeing stopped before mood improved, in both courses (BDI-II was rated daily).",
                  "Low", "Both measures are self-report, so the order rests on her ratings alone.",
                  "Daily mood and urge ratings through a repeat course.")],
          related=[("schweickert-1997", "Methylphenidate for ADHD curbing bulimic bingeing"),
                   ("dukarm-2005", "Six bulimia patients abstinent on dextroamphetamine for ADHD")])

b.save()
